if(r.message)body+=`<p class="result-summary">${esc(j.action==='capacity_close'?'Failed Apply acknowledged. This acknowledgement submits no infrastructure change and does not roll back changes from the Apply. Review current capacity before a fresh plan.':r.message)}</p>`;else if(r.status&&!hasBW)body+=`<p class="result-summary">Result: ${esc(r.status)}</p>`;
