function renderCapacity(){
  if(!capacity)return;
  const op=capacity.operation,pending=Boolean(capacityPending()),locked=pending||Boolean(replacementPending());
  $('#capacity-connection-state').textContent=capacity.configured?'Connected':'Setup required';
  $('#capacity-connection-state').className=`badge ${capacity.configured?'good':''}`;
  if(!connectionDirty&&document.activeElement!==$('#capacity-stack-id'))$('#capacity-stack-id').value=capacity.stack_id||'';
  $('#capacity-desired').textContent=capacity.desired??'—';$('#capacity-ready').textContent=capacity.ready??'—';
  const names=new Set(capacity.pool_members||[]);$('#capacity-rdma-ready').textContent=env?env.nodes.filter(n=>names.has(n.name)&&n.ready&&!n.issues.length&&!n.host_issues.length&&n.devices.some(d=>d.valid!==false)).length:'—';
  $('#capacity-confirm-label').textContent=`Type ${env.environment_name} to confirm this environment`;
  $('#capacity-readiness').disabled=busy||locked||!capacity.configured;
  $('#capacity-connect').disabled=busy||locked;$('#capacity-target').disabled=busy||locked;
  $('#capacity-plan').disabled=busy||locked||!capacity.configured||Boolean(capacity.error)||!capacityCheck?.can_plan||capacityCheck.target!==Number($('#capacity-target').value)||Date.now()/1000-capacityCheck.checked_at>300;
  $('#capacity-provisioned').textContent=capacity.counts?.provisioned??'—';
  $('#capacity-registered').textContent=capacity.counts?.registered??capacity.observed??'—';
  $('#capacity-plan').textContent=capacity.reconciliation_needed?'Generate reconciliation plan':'Generate scale plan';
  const failure=op&&(op.outcome==='failed'||['APPLY_FAILED','CLOSED_FAILED'].includes(op.phase));
  const failureText='Apply failed; infrastructure may be partially provisioned and was not rolled back. '+(op?.phase==='CLOSED_FAILED'?'Failure acknowledged. Choose a corrective target, check prerequisites, then review a fresh plan.':'Wait for OCI work to finish, then acknowledge the failed Apply and create a fresh plan.');
  const operationMarkup=op?`<div class="notice"><strong>${esc(failure?(op.phase==='CLOSED_FAILED'?'FAILED APPLY ACKNOWLEDGED':'APPLY FAILED'):op.phase.replaceAll('_',' '))} · ${esc(op.before)} → ${esc(op.target)} workers</strong><p>${failure?failureText:op.phase==='AWAITING_REVIEW'?'Infrastructure has not been resized. Review the size-only plan and apply it, or discard the target.':op.phase==='DISCARDED'?'Previous stack target restored; no resize was applied.':op.phase==='COMPLETE'?`Operation finished · RDMA readiness ${esc(op.readiness||'not verified')}. Review the result below.`:op.phase==='PLAN_BLOCKED'?'Scaling was not applied. Review the blocked fields, then discard the target before a new plan.':'Requested stack target may differ from running capacity. A plan alone does not resize workers. This operation is retained across service restarts.'}</p>${op.observed_capacity?`<p>At failure review: requested ${esc(op.observed_capacity.requested)}, provisioned ${esc(op.observed_capacity.provisioned)}, registered ${esc(op.observed_capacity.registered)}, Ready ${esc(op.observed_capacity.ready)}. Current counts are shown above.</p>`:''}${capacity.timing?`<h4>Time until usable RDMA capacity</h4><table><tr><th>Milestone</th><th>Seconds since apply</th></tr>${Object.entries(capacity.timing.seconds_since_apply).map(([k,v])=>`<tr><td>${esc(k.replaceAll('_',' '))}</td><td>${v==null?'Not observed':Number(v).toFixed(1)}</td></tr>`).join('')}</table><p>${esc(capacity.timing.note)}</p>${op.node_stage_evidence?`<table><tr><th>New worker</th><th>Registered</th><th>Kubernetes Ready</th></tr>${op.node_stage_evidence.map(n=>`<tr><td>${esc(n.name)}</td><td>${esc(n.registered_at||'Unknown')}</td><td>${esc(n.ready_at||'Unknown')}</td></tr>`).join('')}</table>`:''}`:''}${op.timeline?`<details><summary>Observed capacity timeline</summary>${op.timeline.map(e=>`<p>${esc(e.phase)} · ${esc(time(e.observed_at))}</p>`).join('')}${Object.entries(op.milestones||{}).map(([k,v])=>`<p>${esc(k)} · ${esc(time(v))}</p>`).join('')}<p>Observation times; provisioning and authentication substage durations are not independently measured.</p></details>`:''}${op.capacity_report?`<details><summary>OCI capacity report before planning</summary><pre>${esc(JSON.stringify(op.capacity_report,null,2))}</pre></details>`:''}${op.apply_capacity_report?`<details open><summary>OCI capacity report before apply</summary><pre>${esc(JSON.stringify(op.apply_capacity_report,null,2))}</pre></details>`:''}${op.blocked_reason?`<p class="error">${esc(op.blocked_reason)}</p>`:''}${op.plan_job_id?`<small>Plan job: ${esc(op.plan_job_id)}</small>`:''}${op.apply_job_id?`<small>Apply job: ${esc(op.apply_job_id)}</small>`:''}${op.review?`<details><summary>Reviewed Terraform changes</summary><pre>${esc(JSON.stringify(op.review.changes,null,2))}</pre></details>`:''}${op.expires_at&&op.phase==='AWAITING_REVIEW'?`<small>Plan approval expires ${esc(time(op.expires_at))}</small>`:''}</div>`:'';
  const operationElement=$('#capacity-operation');if(operationElement._rendered!==operationMarkup){operationElement.innerHTML=operationMarkup;operationElement._rendered=operationMarkup;}
  const visible={apply:pending&&op.phase==='AWAITING_REVIEW'&&Date.now()/1000<op.expires_at,discard:pending&&!op.apply_job_id&&op.phase!=='SUBMITTING_APPLY',resume:pending&&['PLAN_RUNNING','SUBMITTING_PLAN','APPLY_RUNNING','SUBMITTING_APPLY','VERIFYING_NODES','APPLY_FAILED'].includes(op.phase),close:pending&&op.phase==='APPLY_FAILED'};
  for(const action of ['apply','discard','resume','close']){const button=$('#capacity-'+action);button.hidden=!visible[action];button.disabled=busy;}
  enforceRequestLocks();
}
